use crate::Observation;
use serde::de::{self, IgnoredAny, MapAccess, SeqAccess, Visitor};
use serde::{Deserialize, Deserializer};
use serde_json::Value;
use std::fmt;

pub(crate) struct WireObservation(pub Observation<Value>);

#[derive(Deserialize)]
#[serde(field_identifier, rename_all = "kebab-case")]
enum Field {
    Kind,
    Value,
    Values,
    Reason,
    Message,
}

fn field<'de, T: Deserialize<'de>, M: MapAccess<'de>>(
    map: &mut M,
    slot: &mut Option<T>,
    name: &'static str,
) -> Result<(), M::Error> {
    if slot.is_some() {
        return Err(de::Error::duplicate_field(name));
    }
    *slot = Some(map.next_value()?);
    Ok(())
}

impl<'de> Deserialize<'de> for WireObservation {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        struct ObservationVisitor;
        impl<'de> Visitor<'de> for ObservationVisitor {
            type Value = WireObservation;

            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                formatter.write_str("a tagged observation")
            }

            fn visit_map<M: MapAccess<'de>>(self, mut map: M) -> Result<Self::Value, M::Error> {
                let mut kind: Option<String> = None;
                let mut value = None;
                let mut values = None;
                let mut reason = None;
                let mut message = None;
                while let Some(key) = map.next_key()? {
                    match key {
                        Field::Kind => field(&mut map, &mut kind, "kind")?,
                        Field::Value => field(&mut map, &mut value, "value")?,
                        Field::Values => field(&mut map, &mut values, "values")?,
                        Field::Reason => field(&mut map, &mut reason, "reason")?,
                        Field::Message => field(&mut map, &mut message, "message")?,
                    }
                }
                let observation = match (kind.as_deref(), value, values, reason, message) {
                    (Some("value"), Some(value), None, None, None) => Observation::Value { value },
                    (Some("allowed"), None, Some(values), None, None) => {
                        Observation::Allowed { values }
                    }
                    (Some("unknown"), None, None, Some(reason), None) => {
                        Observation::Unknown { reason }
                    }
                    (Some("invalid"), None, None, Some(reason), None) => {
                        Observation::Invalid { reason }
                    }
                    (Some("error"), None, None, None, Some(message)) => {
                        Observation::Error { message }
                    }
                    _ => return Err(de::Error::custom("invalid observation kind or fields")),
                };
                Ok(WireObservation(observation))
            }

            fn visit_seq<S: SeqAccess<'de>>(
                self,
                mut sequence: S,
            ) -> Result<Self::Value, S::Error> {
                let kind: String = sequence
                    .next_element()?
                    .ok_or_else(|| de::Error::missing_field("kind"))?;
                let observation = match kind.as_str() {
                    "value" => Observation::Value {
                        value: sequence
                            .next_element()?
                            .ok_or_else(|| de::Error::missing_field("value"))?,
                    },
                    "allowed" => Observation::Allowed {
                        values: sequence
                            .next_element()?
                            .ok_or_else(|| de::Error::missing_field("values"))?,
                    },
                    "unknown" => Observation::Unknown {
                        reason: sequence
                            .next_element()?
                            .ok_or_else(|| de::Error::missing_field("reason"))?,
                    },
                    "invalid" => Observation::Invalid {
                        reason: sequence
                            .next_element()?
                            .ok_or_else(|| de::Error::missing_field("reason"))?,
                    },
                    "error" => Observation::Error {
                        message: sequence
                            .next_element()?
                            .ok_or_else(|| de::Error::missing_field("message"))?,
                    },
                    _ => return Err(de::Error::custom("invalid observation kind")),
                };
                if sequence.next_element::<IgnoredAny>()?.is_some() {
                    return Err(de::Error::custom(
                        "observation sequence requires one payload",
                    ));
                }
                Ok(WireObservation(observation))
            }
        }
        deserializer.deserialize_any(ObservationVisitor)
    }
}

use idealis_oracle::dispatch;
use serde_json::{Value, json};
fn request() -> Value {
    json!({"version":1,"group":"wire","reference":"oracle","implementations":["native","wasm"],"cases":[
        {"id":"one","input":{"source":"model"},"reference":{"kind":"value","value":7},"actual":[{"kind":"value","value":7},{"kind":"value","value":8}]}
    ]})
}
#[test]
fn json_batches_use_the_same_group_and_preserve_inputs_and_failures() {
    let reply = dispatch(&serde_json::to_vec(&request()).unwrap());
    assert_eq!(reply["kind"], "checked");
    assert_eq!(reply["report"]["status"], "mismatch");
    assert_eq!(
        reply["report"]["cases"][0]["case"]["input"],
        json!({"source":"model"})
    );
    assert_eq!(
        reply["report"]["cases"][0]["comparisons"][0]["status"],
        "matched"
    );
    let mut input = request();
    input["cases"][0]["reference"] = json!({"kind":"unknown","reason":"budget"});
    let reply = dispatch(&serde_json::to_vec(&input).unwrap());
    assert_eq!(reply["report"]["status"], "unknown");
}
#[test]
fn malformed_or_vacuous_batches_cannot_match() {
    for path in ["version", "cases", "actual", "extra", "duplicate"] {
        let mut input = request();
        match path {
            "version" => input["version"] = json!(2),
            "cases" => input["cases"] = json!([]),
            "actual" => input["cases"][0]["actual"] = json!([]),
            "extra" => input["typo"] = json!(true),
            "duplicate" => input["implementations"] = json!(["native", "native"]),
            _ => unreachable!(),
        }
        assert_eq!(
            dispatch(&serde_json::to_vec(&input).unwrap())["kind"],
            "error",
            "{path}"
        );
    }
    assert_eq!(dispatch(b"not json")["kind"], "error");
}

#[test]
fn observations_require_exact_variant_fields_in_any_key_order() {
    for observation in [
        json!({"value":null,"kind":"value"}),
        json!({"values":[null,1],"kind":"allowed"}),
        json!({"reason":"budget","kind":"unknown"}),
        json!({"reason":"input","kind":"invalid"}),
        json!({"message":"crash","kind":"error"}),
    ] {
        let mut input = request();
        input["cases"][0]["reference"] = observation.clone();
        assert_eq!(
            dispatch(&serde_json::to_vec(&input).unwrap())["kind"],
            "checked"
        );
        for field in ["value", "values", "reason", "message", "extra"] {
            if observation.get(field).is_some() {
                continue;
            }
            let mut invalid = input.clone();
            invalid["cases"][0]["reference"][field] = json!(null);
            assert_eq!(
                dispatch(&serde_json::to_vec(&invalid).unwrap())["kind"],
                "error",
                "{invalid}"
            );
        }
    }
    for observation in [
        json!({"kind":"value"}),
        json!({"kind":"allowed"}),
        json!({"kind":"unknown","reason":null}),
        json!({"kind":"error","message":3}),
        json!({"kind":"allowed","values":null}),
        json!({"kind":"other","value":1}),
    ] {
        let mut input = request();
        input["cases"][0]["reference"] = observation;
        assert_eq!(
            dispatch(&serde_json::to_vec(&input).unwrap())["kind"],
            "error",
            "{input}"
        );
    }
}

#[test]
fn duplicate_observation_fields_are_rejected() {
    for observation in [
        r#"{"kind":"value","kind":"value","value":7}"#,
        r#"{"kind":"value","value":null,"value":7}"#,
        r#"{"kind":"allowed","values":[],"values":[]}"#,
        r#"{"kind":"unknown","reason":"a","reason":"b"}"#,
        r#"{"kind":"error","message":"a","message":"b"}"#,
    ] {
        let input = format!(
            r#"{{"version":1,"group":"duplicates","reference":"oracle","implementations":["target"],"cases":[{{"id":"one","input":null,"reference":{observation},"actual":[{{"kind":"value","value":7}}]}}]}}"#
        );
        assert_eq!(dispatch(input.as_bytes())["kind"], "error");
    }
}

#[test]
fn wire_observation_acceptance_matches_the_public_serde_contract() {
    let mut observations = vec![json!(null), json!(7), json!("value"), json!([])];
    for kind in [
        json!("value"),
        json!("allowed"),
        json!("unknown"),
        json!("invalid"),
        json!("error"),
        json!("other"),
        json!(0),
        json!(null),
    ] {
        for payload in [
            json!(null),
            json!(7),
            json!([]),
            json!([7]),
            json!("reason"),
            json!({"nested":[1,null]}),
            json!(1.25),
            json!(-0.0),
            json!(u64::MAX),
            json!(i64::MIN),
        ] {
            observations.push(json!([kind, payload]));
            observations.push(json!([kind, payload, 7]));
            for name in ["value", "values", "reason", "message", "extra"] {
                observations.push(json!({"kind":kind, (name):payload}));
            }
        }
    }
    for observation in observations {
        let expected = serde_json::from_slice::<idealis_oracle::Observation<Value>>(
            &serde_json::to_vec(&observation).unwrap(),
        )
        .ok()
        .map(|observation| serde_json::to_value(observation).unwrap());
        for field in ["reference", "actual"] {
            let mut input = request();
            if field == "reference" {
                input["cases"][0][field] = observation.clone();
            } else {
                input["cases"][0][field] = json!([observation, {"kind":"value","value":7}]);
            }
            let response = dispatch(&serde_json::to_vec(&input).unwrap());
            assert_eq!(response["kind"] == "checked", expected.is_some(), "{input}");
            if let Some(expected) = &expected {
                let observation = if field == "reference" {
                    &response["report"]["cases"][0]["reference"]
                } else {
                    &response["report"]["cases"][0]["comparisons"][0]["actual"]
                };
                assert_eq!(observation, expected, "{input}");
            }
        }
    }
}

#[test]
fn observation_tag_may_follow_its_payload() {
    let input = serde_json::to_string(&request()).unwrap().replace(
        r#"{"kind":"value","value":7}"#,
        r#"{"value":7,"kind":"value"}"#,
    );
    assert_eq!(
        dispatch(input.as_bytes()),
        dispatch(&serde_json::to_vec(&request()).unwrap())
    );
}

use idealis_oracle::{dispatch, dispatch_json};
use serde_json::{Value, json};

#[test]
fn byte_output_preserves_complete_reports_for_values_and_failure_observations() {
    for observation in [
        json!({"kind":"value","value":{"nested":[1,true,null,{"field":"x"}]}}),
        json!({"kind":"allowed","values":[1,2]}),
        json!({"kind":"unknown","reason":"budget"}),
        json!({"kind":"invalid","reason":"input"}),
        json!({"kind":"error","message":"crash"}),
    ] {
        let input = json!({"version":1,"group":"bytes","reference":"oracle","implementations":["target"],"cases":[{"id":"input","input":{"source":"retained"},"reference":observation,"actual":[{"kind":"value","value":2}]}]});
        let bytes = serde_json::to_vec(&input).unwrap();
        let output: Value = serde_json::from_slice(&dispatch_json(&bytes)).unwrap();
        assert_eq!(output, dispatch(&bytes));
        assert_eq!(
            output["report"]["cases"][0]["case"]["input"],
            json!({"source":"retained"})
        );
    }
}
#[test]
fn malformed_or_empty_batches_are_errors() {
    let invalid = dispatch_json(b"invalid");
    assert_eq!(
        serde_json::from_slice::<Value>(&invalid).unwrap(),
        dispatch(b"invalid")
    );
    let empty = dispatch_json(
        br#"{"version":1,"group":"empty","reference":"oracle","implementations":[],"cases":[]}"#,
    );
    assert_eq!(
        serde_json::from_slice::<Value>(&empty).unwrap()["kind"],
        "error"
    );
}

use criterion::{BatchSize, Criterion, criterion_group, criterion_main};
use serde_json::{Value, json};
use std::hint::black_box;
use std::time::Duration;

fn payload(count: usize, width: usize, failure: bool) -> Vec<u8> {
    let value = json!({"name":"model-observation","values":(0..width).map(|index| json!({"index":index,"enabled":index%2==0,"tuple":[index,null,"value"]})).collect::<Vec<_>>()});
    serde_json::to_vec(&json!({"version":1,"group":"wire-bench","reference":"oracle","implementations":["target"],"cases":(0..count).map(|index| json!({"id":format!("case-{index}"),"input":{"index":index},"reference":{"kind":"value","value":value},"actual":[if failure {json!({"kind":"unknown","reason":"budget"})} else {json!({"kind":"value","value":value})}]})).collect::<Vec<_>>()})).unwrap()
}
fn measurements(criterion: &mut Criterion) {
    for (name, count, width, failure) in [
        ("single", 1, 1, false),
        ("batch-32", 32, 8, false),
        ("nested-256", 1, 256, false),
        ("unknown", 1, 8, true),
    ] {
        let input = payload(count, width, failure);
        let expected = idealis_oracle::dispatch(&input);
        assert_eq!(
            expected["report"]["status"],
            if failure { "unknown" } else { "matched" }
        );
        assert_eq!(
            serde_json::from_slice::<Value>(&idealis_oracle::dispatch_json(&input)).unwrap(),
            expected
        );
        criterion.bench_function(&format!("wire-value/{name}"), |bencher| {
            bencher.iter_batched(
                || (),
                |_| idealis_oracle::dispatch(black_box(&input)),
                BatchSize::SmallInput,
            )
        });
        criterion.bench_function(&format!("wire-bytes/{name}"), |bencher| {
            bencher.iter_batched(
                || (),
                |_| idealis_oracle::dispatch_json(black_box(&input)),
                BatchSize::SmallInput,
            )
        });
    }
}
criterion_group! { name=benches; config=Criterion::default().sample_size(20).warm_up_time(Duration::from_millis(500)).measurement_time(Duration::from_secs(1)); targets=measurements }
criterion_main!(benches);

